var SHADER;
var ZOOM = 5.0;
var ZOOM_SPEED = 0.001;
var OFFSET = [0,0];
var OFFSET_SPEED=0.0005;
var STEPS = 50;
var COLOUR_ROOTS=false;
var ROOTS = [1,0, -0.5, Math.sqrt(3.0)/2.0, -0.5, -Math.sqrt(3.0)/2.0]
var GRABBING = -1;
var START_ZOOM = -1;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(100);
	frameRate(240);

	SHADER = createShader(vs,fs)

	//disable right click
	for (let element of document.getElementsByClassName("p5Canvas")) {
    element.addEventListener("contextmenu", (e) => e.preventDefault());
  }
}

function GetScreenPos(x,y)
{
	x = (x - width/2) / max(width, height);
	y = ((height-y) - height/2) / max(width, height);
	x*=ZOOM;
	y*=ZOOM;

	x+=OFFSET[0];
	y+=OFFSET[1];

	return [x,y];
}

function mousePressed()
{
	if (mouseButton==CENTER)
	{
		START_ZOOM = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
		return;
	}

	if (!COLOUR_ROOTS) return;
	let pos = GetScreenPos((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	for (let i = 0; i < ROOTS.length; i+=1)
	{
		let x = ROOTS[i];
		let y = ROOTS[i+1];

		let dst = (x-pos[0])**2 + (y-pos[1])**2;

		if (dst < 0.01)
			GRABBING=i;
	}
}
function mouseReleased()
{
	if (mouseButton==CENTER) START_ZOOM=-1;
	if (mouseButton==LEFT) GRABBING=-1;
}
function mouseWheel(event) {
	ZOOM += ZOOM*ZOOM_SPEED*deltaTime * event.delta * 0.025;
}

function draw() {
	clear();

	//player input
	if (keyIsDown(38)) ZOOM -= ZOOM*ZOOM_SPEED*deltaTime;
	if (keyIsDown(40)) ZOOM += ZOOM*ZOOM_SPEED*deltaTime;

	if (keyIsDown(68)) OFFSET[0] += OFFSET_SPEED*deltaTime*ZOOM;
	if (keyIsDown(65)) OFFSET[0] -= OFFSET_SPEED*deltaTime*ZOOM;
	if (keyIsDown(87)) OFFSET[1] += OFFSET_SPEED*deltaTime*ZOOM;
	if (keyIsDown(83)) OFFSET[1] -= OFFSET_SPEED*deltaTime*ZOOM;

	//run shader
	shader(SHADER);
  SHADER.setUniform('resolution', [width, height]); //parse the resolution to the shader
	SHADER.setUniform("zoom",ZOOM);
	SHADER.setUniform("offset",OFFSET);
	SHADER.setUniform("steps",STEPS);
	SHADER.setUniform("roots", ROOTS);
	SHADER.setUniform("colour_roots",COLOUR_ROOTS);
	quad(-1, -1, -1, 1, 1, 1, 1, -1);
	resetShader();

	//update stats
	settings.setValue("Delta Time", int(deltaTime));
	settings.setValue("FPS", int(frameRate()));
	settings.setValue("Zoom", ZOOM);

	if (GRABBING!=-1)
	{
