		let delta = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - START_ZOOM;
		ZOOM += ZOOM*ZOOM_SPEED*deltaTime*delta*0.01;
	}
}

// === Tab: shader ===
//DEFINE SHADER
let vs = `
  precision highp float;

  attribute vec3 aPosition;

  void main() {
     vec4 positionVec4 = vec4(aPosition, 1.0);

     gl_Position = positionVec4;
}
`;
let fs = `
  precision highp float;

  uniform vec2 resolution;
	uniform float zoom;
	uniform vec2 offset;
	uniform int steps;
	uniform bool colour_roots;
	uniform vec2 roots[3];

	//util
	float QuickLength(vec2 v) {
		return v.x*v.x + v.y*v.y;
	}
	float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
	}

	//complex number functions
	vec2 MulComplex(vec2 a,vec2 b)
  {
    float img = (a.y*b.x) + (a.x*b.y);
    float real = -(a.y*b.y) + (a.x*b.x);
    return vec2(real, img);
  }
	vec2 PowComplex(vec2 a, int n)
	{
		vec2 o = a;
		for (int i = 0; i < 100; i++)
		{
			if (i > n-2)
				break;
			o = MulComplex(o,a);
		}
		return o;
	}
	vec2 Conjugate(vec2 com)
  {
    return vec2(com.x, -com.y);
  }
	vec2 DivComplex(vec2 a,vec2 b)
  {
    vec2 c = Conjugate(b);
    vec2 top = MulComplex(a,c);
    vec2 bottom = MulComplex(b,c);
		return top / bottom.r;
  }


	//define function
	vec2 Function(vec2 x)
	{
		vec2 compOut = vec2(1,0);
		for (int i = 0; i < 3; i++)
		{
			compOut = MulComplex(compOut, x-roots[i]);
		}
		return compOut;
	}
	vec2 Derivative(vec2 x)
	{
		 vec2 compOut = vec2(0,0);
		 for (int n = 0; n < 3; n++)
		 {
		 		vec2 term = vec2(1,0);
		 		for (int i = 0; i < 3; i++)
				{
					if (i==n) continue;
					term = MulComplex(term, x-roots[i]);
				}
				compOut += term;
		 }

		 return compOut;
	}

	vec2 ApplyNewtonsMethod(vec2 n)
	{
		return n - DivComplex(Function(n), Derivative(n));
	}

  void main() {
		//normalise coordinates
		vec2 uv = (gl_FragCoord.xy - resolution.xy/2.0) / min(resolution.x, resolution.y);
		uv*=zoom;
		uv+=offset;

		vec2 point = uv;
		int currentSteps = 0;
		for (int i = 0; i < 10000; i++)
		{
			if (i >= steps) break;
			vec2 newPoint = ApplyNewtonsMethod(point);
			point = newPoint;
		}

		if (colour_roots)
		{
			for (int i = 0; i < 3; i++)
			{
				if (QuickLength(roots[i] -uv) < 0.0001 * zoom * zoom)
				{
					gl_FragColor = vec4(1,1,1,1);
					return;
				}
			}
		}

		//find closest root
		int closest = -1;
		float dst = 10000.0;
		for (int i = 0; i < 3; i ++)
		{
			float tDst = QuickLength(roots[i] - point);
			if (tDst < dst)
			{
				closest = i;
				dst = tDst;
			}		
		}

		vec3 col = vec3(rand(vec2(closest, 0)), rand(vec2(closest,1)), rand(vec2(closest,2)));
    gl_FragColor = vec4(col,1); //return the uv as R and G
}
`;

